const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split('\n');
const n = Number(input[0]);
const instructions = input[1];

let room = 1;

for (let i = 0; i < n; i++) {
  if (instructions[i] === 'E') {
    room = 2 * room;
  } else {
    room = 2 * room + 1;
  }
}

console.log(room);
